<script setup>
import { ref } from 'vue'; import { router, useForm } from '@inertiajs/vue3';
const props=defineProps({administrators:Array,currentUser:Object}); const createForm=useForm({name:'',email:'',password:'',password_confirmation:''}); const profileForm=useForm({name:props.currentUser.name,email:props.currentUser.email}); const passwordForm=useForm({current_password:'',password:'',password_confirmation:''}); const editing=ref(null); const editForm=useForm({name:'',email:''});
const create=()=>createForm.post('/admin/administrateurs',{preserveScroll:true,onSuccess:()=>createForm.reset()}); const updateProfile=()=>profileForm.put('/admin/mon-compte',{preserveScroll:true}); const updatePassword=()=>passwordForm.put('/admin/mon-compte/mot-de-passe',{preserveScroll:true,onSuccess:()=>passwordForm.reset()}); const remove=a=>confirm(`Supprimer l’accès administrateur de ${a.name} ?`)&&router.delete(`/admin/administrateurs/${a.id}`,{preserveScroll:true}); function edit(a){editing.value=a;editForm.defaults({name:a.name,email:a.email});editForm.reset()} function saveEdit(){editForm.put(`/admin/administrateurs/${editing.value.id}`,{preserveScroll:true,onSuccess:()=>editing.value=null})}
</script>
<template><div class="grid gap-6 xl:grid-cols-2"><section class="rounded-3xl bg-white p-6"><h2 class="font-serif text-2xl">Mon compte</h2><form @submit.prevent="updateProfile" class="mt-5 space-y-3"><input v-model="profileForm.name" class="w-full rounded-xl border px-4 py-3"/><input v-model="profileForm.email" type="email" class="w-full rounded-xl border px-4 py-3"/><button class="rounded-full bg-ink px-5 py-3 text-sm font-bold text-white">Enregistrer</button></form><form @submit.prevent="updatePassword" class="mt-7 space-y-3 border-t pt-6"><input v-model="passwordForm.current_password" type="password" placeholder="Mot de passe actuel" class="w-full rounded-xl border px-4 py-3"/><input v-model="passwordForm.password" type="password" placeholder="Nouveau mot de passe" class="w-full rounded-xl border px-4 py-3"/><input v-model="passwordForm.password_confirmation" type="password" placeholder="Confirmation" class="w-full rounded-xl border px-4 py-3"/><button class="rounded-full border px-5 py-3 text-sm font-bold">Modifier le mot de passe</button></form></section><section class="rounded-3xl bg-white p-6"><h2 class="font-serif text-2xl">Nouvel administrateur</h2><form @submit.prevent="create" class="mt-5 space-y-3"><input v-model="createForm.name" placeholder="Nom" class="w-full rounded-xl border px-4 py-3"/><input v-model="createForm.email" type="email" placeholder="E-mail" class="w-full rounded-xl border px-4 py-3"/><input v-model="createForm.password" type="password" placeholder="Mot de passe" class="w-full rounded-xl border px-4 py-3"/><input v-model="createForm.password_confirmation" type="password" placeholder="Confirmation" class="w-full rounded-xl border px-4 py-3"/><button class="rounded-full bg-ink px-5 py-3 text-sm font-bold text-white">Créer</button></form></section><section class="overflow-hidden rounded-3xl bg-white xl:col-span-2"><div class="border-b p-5"><h2 class="font-serif text-2xl">Administrateurs de l’école</h2></div><div class="divide-y"><div v-for="a in administrators" :key="a.id" class="flex items-center justify-between p-5"><div><strong>{{a.name}}</strong><p class="text-sm text-black/45">{{a.email}}</p></div><span v-if="a.id===currentUser.id" class="text-xs font-bold text-black/35">Vous</span><div v-else class="flex gap-2"><button @click="edit(a)" class="grid h-9 w-9 place-items-center rounded-full bg-black/5" title="Modifier">✎</button><button @click="remove(a)" class="grid h-9 w-9 place-items-center rounded-full bg-red-50 text-red-500" title="Supprimer">×</button></div></div></div></section></div><div v-if="editing" class="fixed inset-0 z-50 grid place-items-center bg-black/45 p-4" @click.self="editing=null"><form @submit.prevent="saveEdit" class="w-full max-w-md rounded-3xl bg-white p-7"><h2 class="font-serif text-3xl">Modifier l’administrateur</h2><input v-model="editForm.name" class="mt-5 w-full rounded-xl border px-4 py-3"/><input v-model="editForm.email" type="email" class="mt-3 w-full rounded-xl border px-4 py-3"/><p v-if="Object.keys(editForm.errors).length" class="mt-3 text-sm text-red-600">{{Object.values(editForm.errors)[0]}}</p><div class="mt-5 flex gap-2"><button type="button" @click="editing=null" class="flex-1 rounded-full border py-3">Annuler</button><button class="flex-1 rounded-full bg-ink py-3 font-bold text-white">Enregistrer</button></div></form></div></template>
